// Generated by node build-bookmarklet.cjs.
(function start(template) {
  const sourceUrl = window.BERGER_BOOT?.sourceUrl || location.href;
  const parsed = new URL(sourceUrl);
  const value = Number(parsed.searchParams.get('round'));
  const round = Number.isInteger(value) && value >= 1 && value <= 5 ? value : 1;
  const config = JSON.stringify({BERGER_LIVE:true, BERGER_ROUND:round, BERGER_SOURCE_URL:sourceUrl}).replace(/</g, '\\u003c');
  document.open();
  document.write(template.replace('__BERGER_CONFIG__', () => config));
  document.close();
})("<!doctype html>\n<html lang=\"sv\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Bergergrupper · Uppsala Schackfestival</title><style>:root { font-family: Segoe UI, Arial, sans-serif; color: #202d2b; background: #f5f6f2; }\r\n* { box-sizing: border-box; }\r\nbody { margin: 0; }\r\nbutton, select, input { font: inherit; }\r\nbutton, a, select { touch-action: manipulation; }\r\nbutton { cursor: pointer; background: #215847; color: white; border: 1px solid #215847; border-radius: 6px; padding: 7px 12px; font-weight: 600; }\r\nbutton:hover { filter: brightness(.93); }\r\nbutton:disabled { opacity: .4; cursor: default; }\r\na { color: #215847; }\r\nheader { height: 44px; border-bottom: 1px solid #dfe3dc; display: flex; align-items: center; justify-content: space-between; padding: 0 5%; gap: 20px; background: white; }\r\nheader > span { font-size: 11px; letter-spacing: 1.8px; color: #727e76; }\r\nheader > a:last-child { font-size: 13px; text-decoration: none; }\r\n.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 17px; text-decoration: none; }\r\n.mark { background: #215847; color: white; padding: 0 7px; border-radius: 6px; font-size: 23px; }\r\nmain { max-width: 1240px; margin: auto; padding: 12px 24px; }\r\n.intro { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 10px; }\r\nh1 { font-size: 25px; letter-spacing: -.6px; margin: 0; }\r\nh2 { font-size: 16px; margin: 0; }\r\nh3 { font-size: 16px; }\r\n.secondary { background: white; color: #344b40; border-color: #d8dfd7; white-space: nowrap; }\r\n.toolbar { background: #e9eee6; border: 1px solid #dbe3d6; border-radius: 8px; display: flex; align-items: center; gap: 14px; padding: 8px 14px; margin-bottom: 8px; }\r\n.toolbar > div:first-child { display: flex; align-items: center; gap: 8px; margin-right: auto; }\r\n.toolbar label { font-size: 12px; font-weight: 600; }\r\n.group-summary { margin: 0 0 8px; font-size: 12px; color: #586c50; }\r\n.prefix-form { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; font-size: 13px; }\r\n.prefix-form input { width: 90px; padding: 5px 8px; border: 1px solid #d3dcd0; border-radius: 5px; font: inherit; }\r\n.prefix-form small { color: #63735d; }\r\n.display-mode .prefix-form { display: none; }\r\n.roundpicker { display: flex; gap: 6px; }\r\n.roundpicker button, .roundpicker select { border: 1px solid #d3dcd0; border-radius: 5px; background: white; padding: 4px 10px; color: #263e32; }\r\n.roundpicker select { font-weight: 600; }\r\n.boardlist { border: 1px solid #dce2d9; border-radius: 8px; overflow: hidden; background: white; }\r\n.tablehead { padding: 8px 14px; }\r\n.tablehead p { font-size: 11px; color: #788078; margin: 3px 0 0; }\r\n.tablehead h2 span { color: #738171; font-weight: 400; margin-left: 8px; }\r\n.tablewrap { overflow: auto; }\r\ntable { border-collapse: collapse; width: 100%; text-align: left; white-space: nowrap; }\r\nth { background: #f4f6f1; color: #707c70; font-size: 11px; letter-spacing: 1px; text-transform: uppercase; padding: 6px 16px; border-block: 1px solid #e7ebe3; }\r\ntd { padding: 5px 16px; border-bottom: 1px solid #edf0e9; font-size: 14px; line-height: 1.25; }\r\ntr.groupstart td { border-top: 2px solid #dbe3d5; }\r\n.badge { display: inline-flex; align-items: center; gap: 8px; background: #eef3e9; border: 1px solid #dce6d4; border-radius: 5px; padding: 2px 7px; color: #466342; font-weight: 600; }\r\n.badge small { font-weight: 400; color: #7c8b75; }\r\ntd:nth-child(2) { color: #53634e; font-variant-numeric: tabular-nums; font-weight: 600; }\r\n.elo { color: #687864; font-variant-numeric: tabular-nums; text-align: right; }\r\nth.elo { text-align: right; }\r\n.paper-result { display: none; }\r\n.groupstatus { display: flex; flex-wrap: wrap; gap: 8px; padding: 5px 14px; background: #fbfcf9; }\r\n.groupstatus span { font-size: 11px; color: #61735d; border-radius: 4px; background: #edf2e8; padding: 3px 7px; }\r\n.groupstatus .missing { background: #fbf1df; color: #8d6a2c; }\r\n#notice { font-size: 12px; line-height: 1.35; margin-bottom: 8px; color: #716344; }\r\n#notice:empty { display: none; }\r\n.help { margin-top: 8px; font-size: 13px; color: #63735d; line-height: 1.8; }\r\n.help summary { cursor: pointer; }\r\n.empty { text-align: center; color: #7b8575; padding: 40px; }\r\ndialog { border: 1px solid #d8dfd0; border-radius: 12px; max-width: 620px; width: calc(100% - 30px); padding: 28px; color: #2c4030; }\r\ndialog::backdrop { background: #17291d88; }\r\ndialog p { font-size: 13px; line-height: 1.7; color: #6b7962; }\r\n.dialogheading { display: flex; justify-content: space-between; align-items: center; }\r\nhr { border: 0; border-top: 1px solid #e4e9df; margin: 25px 0; }\r\n.bookmark { display: inline-block; padding: 10px; background: #edf3e7; border-radius: 5px; margin: 5px 0; }\r\n.install-note { margin: 0 0 10px; font-size: 13px; color: #586c50; line-height: 1.6; }\r\n.install-note .bookmark { padding: 3px 9px; margin: 0 4px; font-weight: 600; cursor: grab; }\r\ndialog li { margin: 12px 0; line-height: 1.6; font-size: 14px; }\r\n#bookmarkCode { width: 100%; height: 110px; margin-top: 10px; }\r\n.live-mode .install-note, .live-mode #installButton { display: none; }\r\n.display-mode .install-note { display: none; }\r\n:focus-visible { outline: 3px solid #a7bd72; outline-offset: 3px; }\r\n.display-mode header, .display-mode .intro, .display-mode #refresh, .display-mode #print,\r\n.display-mode #notice, .display-mode .tablehead p, .display-mode .groupstatus, .display-mode .help, .display-mode .group-summary { display: none; }\r\n.display-mode main { max-width: none; padding: 8px 16px; }\r\n.display-mode .toolbar { margin-bottom: 6px; }\r\n.display-mode .tablehead { padding: 6px 16px; }\r\n.display-mode td { height: clamp(24px, calc((100dvh - 140px) / var(--board-count, 15)), 64px); font-size: clamp(14px, 2.1vh, 24px); padding-block: 2px; }\r\n.display-mode .badge small { font-size: .6em; }\r\n.display-mode #notice.warning { display: block; }\r\n@media (max-width: 760px) {\r\n  header { padding: 0 15px; }\r\n  header > span { display: none; }\r\n  main { padding: 10px; }\r\n  .intro { flex-wrap: wrap; gap: 8px; }\r\n  h1 { font-size: 23px; }\r\n  .toolbar { flex-wrap: wrap; gap: 8px; padding: 8px; }\r\n  th { padding: 6px 10px; }\r\n  td { padding: 5px 10px; }\r\n}\r\n@page { size: A4 portrait; margin: 12mm; }\r\n@media print {\r\n  body { background: white; color: black; }\r\n  header, .intro, .toolbar, .prefix-form, .group-summary, #notice, .groupstatus, .help, .install-note, dialog { display: none !important; }\r\n  main, .display-mode main { max-width: none; padding: 0; }\r\n  .boardlist, .tablewrap { overflow: visible; border: 0; border-radius: 0; }\r\n  .tablehead, .display-mode .tablehead { padding: 0 0 5mm; }\r\n  .tablehead h2 { font-size: 16pt; color: black; }\r\n  .tablehead h2 span { color: black; }\r\n  .tablehead p { display: none; }\r\n  table { white-space: normal; table-layout: fixed; }\r\n  th { background: white; color: black; font-size: 10pt; letter-spacing: 0; padding: 2mm; border: 1px solid black; }\r\n  td, .display-mode td { height: 12mm; padding: 2mm; font-size: 11pt; color: black; border: 1px solid black; overflow-wrap: anywhere; }\r\n  tr.groupstart td { border-top: 2px solid black; }\r\n  th:nth-child(1) { width: 13%; }\r\n  th:nth-child(2) { width: 8%; }\r\n  th:nth-child(3), th:nth-child(5) { width: 25%; }\r\n  th:nth-child(4), th:nth-child(6) { width: 8%; }\r\n  th:nth-child(7) { width: 13%; }\r\n  td.elo, th.elo { color: black; padding-inline: 1mm; font-size: 9pt; white-space: nowrap; }\r\n  .paper-result { display: table-cell; }\r\n  .badge { border: 0; background: white; padding: 0; color: black; gap: 4px; }\r\n  .badge small { color: black; font-size: 8pt; }\r\n  .display-mode .badge small { font-size: 8pt; }\r\n  td:nth-child(2) { color: black; }\r\n  thead { display: table-header-group; }\r\n  tr { break-inside: avoid; }\r\n}\r\n</style></head>\n<body>\n<header><a class=\"brand\" href=\"./\"><span class=\"mark\">♜</span> Bergergrupper</a><span>UPPSALA SCHACKFESTIVAL 2026</span><a href=\"https://member.schack.se/ShowTournamentServlet?id=19095\" target=\"_blank\" rel=\"noopener\">Öppna turneringen ↗</a></header>\n<main>\n<div class=\"intro\"><h1>Alla bord. En överblick.</h1><button id=\"installButton\" class=\"secondary\">Installera bokmärke</button></div>\n<p class=\"install-note\">Dra <a id=\"bookmarklet\" class=\"bookmark\">♜ Bergergrupper</a> till bokmärkesfältet. Öppna sedan <a href=\"https://member.schack.se/ShowTournamentServlet?id=19095\" target=\"_blank\" rel=\"noopener\">turneringen på schack.se</a> och klicka på bokmärket.</p>\n<form id=\"prefixForm\" class=\"prefix-form\"><label for=\"prefix\">Prefix</label><input id=\"prefix\" type=\"text\" value=\"W2\" placeholder=\"t.ex. W1\" autocomplete=\"off\" spellcheck=\"false\"><small>Tryck Enter för att byta</small></form><p id=\"detectedGroups\" class=\"group-summary\"></p><section class=\"toolbar\" aria-label=\"Rondval\"><div><label for=\"round\">Rond</label><div class=\"roundpicker\"><button id=\"previous\" aria-label=\"Föregående rond\">←</button><select id=\"round\" aria-label=\"Välj rond\"></select><button id=\"next\" aria-label=\"Nästa rond\">→</button></div></div><button id=\"displayMode\" class=\"secondary\" aria-pressed=\"false\">Visningsläge</button><button id=\"refresh\" class=\"secondary\">↻ Uppdatera</button><button id=\"print\">Skriv ut bordslista</button></section>\n<div id=\"notice\" role=\"status\" aria-live=\"polite\"></div>\n<section class=\"boardlist\"><div class=\"tablehead\"><div><h2><span id=\"tournamentTitle\">Uppsala Schackfestival 2026</span> · Bordslista <span id=\"roundLabel\"></span></h2><p id=\"scope\">W2-1–5 · 15 bord</p></div></div><div class=\"tablewrap\"><table><thead><tr><th scope=\"col\">Grupp</th><th scope=\"col\">Bord</th><th scope=\"col\">♙ Vit</th><th scope=\"col\" class=\"elo\">Elo</th><th scope=\"col\">♟ Svart</th><th scope=\"col\" class=\"elo\">Elo</th><th scope=\"col\" class=\"paper-result\">Resultat</th></tr></thead><tbody id=\"games\"></tbody></table></div><div id=\"groups\" class=\"groupstatus\"></div></section>\n<details class=\"help\"><summary>Så använder du bordslistan</summary><p>Kör bokmärket på member.schack.se. En ny flik öppnas med grupperna som har samma deltagarantal som den första. Sista gruppen ignoreras om den har ett annat antal. Byt rond eller klicka på Uppdatera för att hämta aktuella bordslistor.</p><p>Visningsläge visar alla bord på en gemensam skärm. Skriv ut bordslista ger tomma resultatrutor som deltagarna fyller i för hand. Bokmärket kan kopieras direkt från README på GitHub. Ingen inloggning på den här webbplatsen behövs.</p></details>\n</main>\n<dialog id=\"installation\"><form method=\"dialog\"><div class=\"dialogheading\"><h2>Installera bokmärket</h2><button aria-label=\"Stäng\" class=\"secondary\">✕</button></div></form><ol><li>Visa webbläsarens bokmärkesfält (oftast Ctrl+Skift+B).</li><li>Dra länken <a id=\"dialogBookmarklet\" class=\"bookmark\">♜ Bergergrupper</a> till bokmärkesfältet.</li><li>Öppna <a href=\"https://member.schack.se/ShowTournamentServlet?id=19095\" target=\"_blank\" rel=\"noopener\">turneringen på schack.se</a> och klicka på det sparade bokmärket.</li></ol><p>Om du har det gamla bokmärket: ersätt det med det här. Det nya öppnar bordslistan direkt.</p><button id=\"copyBookmarklet\" class=\"secondary\">Kopiera bokmärkesadressen</button><p id=\"installStatus\" role=\"status\"></p><textarea id=\"bookmarkCode\" aria-label=\"Bokmärkesadress att kopiera\" readonly hidden></textarea></dialog>\n<script>Object.assign(window,__BERGER_CONFIG__);</script><script>'use strict';\nconst LIVE = window.BERGER_LIVE === true;\nlet GROUPS = ['A', 'B', 'C', 'D', 'E'];\nlet IDS = Object.fromEntries(GROUPS.map((group, i) => [group, String(19095 + i)]));\nlet prefix = 'W2';\nlet availableGroups = GROUPS.map((group, i) => ({prefix, number:i + 1, id:IDS[group]}));\nlet groupNumbers = Object.fromEntries(GROUPS.map((group, i) => [group, i + 1]));\nlet detectionNumber = 0;\nlet boardsPerGroup = 3;\nconst $ = id => document.getElementById(id);\nlet games = [];\nlet round = Number(window.BERGER_ROUND) || 1;\nif (!Number.isInteger(round) || round < 1 || round > 5) round = 1;\nlet busy = false;\nlet requestNumber = 0;\nconst failures = new Map();\nfunction groupName(group) { return prefix + '-' + groupNumbers[group]; }\nfunction participantCount(doc, tournamentId) {\n  const ids = new Set();\n  const pairedIds = new Set();\n  for (const element of doc.querySelectorAll('[onclick], a[href]')) {\n    const target = (element.getAttribute('onclick') || '') + ' ' + (element.getAttribute('href') || '');\n    const call = target.match(/postshowindtournamentresultform\\(\\s*['\"](\\d+)['\"]\\s*,\\s*['\"](\\d+)['\"]/i);\n    if (call && call[1] === String(tournamentId)) ids.add(call[2]);\n    const link = target.match(/ShowTournamentParticipantResultServlet\\?([^'\"\\s]+)/i);\n    if (link) {\n      const query = new URLSearchParams(link[1]);\n      const id = query.get('partid');\n      if (query.get('id') === String(tournamentId) && /^\\d+$/.test(id || '')) pairedIds.add(id);\n    }\n  }\n  // Standings can retain replaced players. Pairings reflect the current group size.\n  if (pairedIds.size) return pairedIds.size;\n  if (!ids.size) throw Error('Kunde inte läsa deltagarantalet för turnerings-ID ' + tournamentId + '.');\n  return ids.size;\n}\nfunction selectBergerGroups(definitions, counts) {\n  const firstCount = counts[0];\n  if (!definitions.length || counts.length !== definitions.length || counts.some(n => !Number.isInteger(n) || n < 1)) throw Error('Deltagarantal saknas.');\n  const last = definitions.length - 1;\n  for (let i = 1; i < last; i++) {\n    if (counts[i] !== firstCount) throw Error(definitions[i].prefix + '-' + definitions[i].number + ' har ' + counts[i] + ' deltagare, men första gruppen har ' + firstCount + '. Kontrollera grupperna.');\n  }\n  const ignored = last > 0 && counts[last] !== firstCount ? definitions[last] : null;\n  return {definitions:ignored ? definitions.slice(0, -1) : definitions, participantCount:firstCount, ignored, ignoredCount:ignored ? counts[last] : null};\n}\nfunction discoverGroups(doc) {\n  const found = new Map();\n  for (const link of doc.querySelectorAll('[onclick], a[href]')) {\n    const name = link.textContent.trim().match(/^(.+?)-(\\d+)$/);\n    const target = (link.getAttribute('onclick') || '') + ' ' + (link.getAttribute('href') || '');\n    const id = target.match(/ShowTournamentServlet\\?[^'\"\\s]*\\bid=(\\d+)/);\n    if (!name || !id) continue;\n    const value = {prefix:name[1].trim(), number:Number(name[2]), id:id[1]};\n    found.set(value.prefix + ':' + value.number, value);\n  }\n  return Array.from(found.values()).sort((a, b) => a.prefix.localeCompare(b.prefix, 'sv', {numeric:true}) || a.number - b.number);\n}\nfunction configureGroups(value, count) {\n  const selectedPrefix = value.trim().replace(/-+$/, '');\n  if (!Number.isInteger(count) || count < 1 || count > 26) throw Error('Välj 1–26 grupper.');\n  const definitions = availableGroups.filter(g => g.prefix.toLocaleLowerCase() === selectedPrefix.toLocaleLowerCase()).sort((a, b) => a.number - b.number).slice(0, count);\n  if (definitions.length !== count) throw Error('Alla ' + count + ' grupper med prefix ' + selectedPrefix + ' finns inte på källsidan.');\n  prefix = definitions[0].prefix;\n  GROUPS = definitions.map((_, i) => String.fromCharCode(65 + i));\n  IDS = Object.fromEntries(GROUPS.map((group, i) => [group, definitions[i].id]));\n  groupNumbers = Object.fromEntries(GROUPS.map((group, i) => [group, definitions[i].number]));\n  boardsPerGroup = 3;\n  games = []; failures.clear(); requestNumber++; busy = false;\n  $('prefix').value = prefix;\n  $('detectedGroups').textContent = count + ' grupper';\n}\nasync function loadGroupDocument(definition) {\n  const response = await fetch('https://member.schack.se/ShowTournamentServlet?id=' + definition.id, {cache:'no-store', signal:AbortSignal.timeout(20000)});\n  if (!response.ok) throw Error('Kunde inte läsa ' + definition.prefix + '-' + definition.number + '.');\n  const doc = new DOMParser().parseFromString(await response.text(), 'text/html');\n  const name = (definition.prefix + '-' + definition.number).replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n  if (!new RegExp('(?:^|\\\\s)' + name + '(?=\\\\s|$)').test(doc.title)) throw Error('Fel källgrupp: ' + doc.title);\n  return doc;\n}\nasync function detectGroups(value, sourceDoc = null, sourceId = null) {\n  const selectedPrefix = value.trim().replace(/-+$/, '').toLocaleLowerCase();\n  const definitions = availableGroups.filter(g => g.prefix.toLocaleLowerCase() === selectedPrefix).sort((a, b) => a.number - b.number);\n  if (!definitions.length) throw Error('Inga grupper med prefix ' + value + ' hittades på källsidan.');\n  const request = ++detectionNumber;\n  let configured = false;\n  requestNumber++; busy = true; render();\n  $('notice').className = '';\n  $('notice').textContent = 'Jämför gruppernas deltagarantal…';\n  try {\n    const counts = await Promise.all(definitions.map(async definition => {\n      const doc = sourceDoc && definition.id === sourceId ? sourceDoc : await loadGroupDocument(definition);\n      return participantCount(doc, definition.id);\n    }));\n    if (request !== detectionNumber) return;\n    const selection = selectBergerGroups(definitions, counts);\n    configureGroups(selection.definitions[0].prefix, selection.definitions.length);\n    boardsPerGroup = Math.ceil(selection.participantCount / 2);\n    configured = true;\n    const ignored = selection.ignored;\n    $('detectedGroups').textContent = selection.definitions.length + ' grupper med ' + selection.participantCount + ' deltagare vardera.' + (ignored ? ' ' + ignored.prefix + '-' + ignored.number + ' (' + selection.ignoredCount + ' deltagare) ignoreras.' : ' Sista gruppen ingår.');\n    render(); await refresh();\n  } finally {\n    if (request === detectionNumber) { if (!configured) busy = false; render(); }\n  }\n}\n\nfunction validateGames(rows) {\n  if (!Array.isArray(rows)) throw Error('Ogiltig bordslista.');\n  const seen = new Set();\n  return rows.map(g => {\n    if (!GROUPS.includes(g.group) || String(g.tournamentId) !== IDS[g.group] || !Number.isInteger(g.round) || g.round < 1 || g.round > 5 || !Number.isInteger(g.board) || g.board < 1 || g.board > 100 || typeof g.white !== 'string' || !g.white || typeof g.black !== 'string' || !g.black) throw Error('Ogiltig partirad.');\n    const key = [g.group, g.round, g.board].join(':');\n    if (seen.has(key)) throw Error('Dubblerat bord i källistan.');\n    seen.add(key);\n    const rating = n => n != null && /^\\d{1,4}$/.test(String(n)) ? Number(n) : null;\n    return {group:g.group, tournamentId:IDS[g.group], round:g.round, board:g.board, white:g.white, black:g.black, whiteElo:rating(g.whiteElo), blackElo:rating(g.blackElo)};\n  });\n}\nfunction parseSource(doc, group, selectedRound) {\n  const expected = groupName(group).replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n  if (!new RegExp('(?:^|\\\\s)' + expected + '(?=\\\\s|$)').test(doc.title)) throw Error('Fel källgrupp: ' + doc.title);\n  const selected = doc.querySelector('.selroundheader')?.textContent.match(/Rond\\s+(\\d+)/i);\n  if (selected && Number(selected[1]) !== selectedRound) throw Error('Källan visar en annan rond.');\n  const result = [];\n  let indexes = null;\n  for (const row of doc.querySelectorAll('tr')) {\n    const cells = Array.from(row.children).filter(c => c.matches('td, th'));\n    const text = cells.map(c => c.textContent.trim().replace(/\\s+/g, ' '));\n    if (text.includes('Bord') && text.includes('VIT') && text.includes('SVART')) {\n      indexes = ['Bord', 'VIT', 'SVART'].map(label => text.indexOf(label));\n      indexes.push(text.findIndex((label, i) => label === 'ELO' && i > indexes[1] && i < indexes[2]));\n      indexes.push(text.findIndex((label, i) => label === 'ELO' && i > indexes[2]));\n      continue;\n    }\n    if (!indexes || !/^\\d+$/.test(text[indexes[0]] || '')) continue;\n    const elo = i => /^\\d+$/.test(text[i] || '') ? Number(text[i]) : null;\n    result.push({group, tournamentId:IDS[group], round:selectedRound, board:Number(text[indexes[0]]), white:text[indexes[1]], black:text[indexes[2]], whiteElo:elo(indexes[3]), blackElo:elo(indexes[4])});\n  }\n  if (!result.length) throw Error('Ingen bordslista publicerad.');\n  return validateGames(result);\n}\nasync function fetchGroup(group, selectedRound) {\n  const response = await fetch('https://member.schack.se/ShowTournamentServlet?id=' + IDS[group] + '&round=' + selectedRound, {cache:'no-store', signal:AbortSignal.timeout(20000)});\n  if (!response.ok) throw Error('Källan svarade inte.');\n  return parseSource(new DOMParser().parseFromString(await response.text(), 'text/html'), group, selectedRound);\n}\nfunction currentGames() { return games.filter(g => g.round === round).sort((a, b) => a.group.localeCompare(b.group) || a.board - b.board); }\nfunction boardNumber(g) {\n  return GROUPS.slice(0, GROUPS.indexOf(g.group)).reduce((offset, group) => offset + Math.max(boardsPerGroup, ...games.filter(row => row.group === group).map(row => row.board)), g.board);\n}\nfunction render() {\n  const rows = currentGames();\n  document.documentElement.style.setProperty('--board-count', Math.max(1, rows.length));\n  $('round').value = String(round);\n  $('previous').disabled = round === 1;\n  $('next').disabled = round === 5;\n  $('refresh').disabled = busy;\n  $('print').disabled = busy || !rows.length;\n  $('roundLabel').textContent = ' / Rond ' + round;\n  $('games').replaceChildren();\n  let previousGroup = '';\n  for (const g of rows) {\n    const row = document.createElement('tr');\n    if (g.group !== previousGroup) row.className = 'groupstart';\n    previousGroup = g.group;\n    const cell = text => { const td = document.createElement('td'); td.textContent = text; row.append(td); return td; };\n    const badge = document.createElement('span'); badge.className = 'badge'; badge.textContent = g.group;\n    const label = document.createElement('small'); label.textContent = groupName(g.group); badge.append(label); cell('').append(badge);\n    cell(boardNumber(g)); cell(g.white); cell(g.whiteElo ?? '–').className = 'elo';\n    cell(g.black); cell(g.blackElo ?? '–').className = 'elo'; cell('').className = 'paper-result';\n    $('games').append(row);\n  }\n  if (!rows.length) { const row = document.createElement('tr'), td = document.createElement('td'); td.colSpan = 7; td.className = 'empty'; td.textContent = busy ? 'Hämtar bordslistor…' : 'Ingen bordslista för denna rond.'; row.append(td); $('games').append(row); }\n  $('groups').replaceChildren();\n  GROUPS.forEach(group => { const count = rows.filter(g => g.group === group).length; const label = document.createElement('span'); label.textContent = `${group} / ${groupName(group)} · ${count ? count + ' bord' : 'saknas'}`; if (!count || failures.get(round)?.includes(group)) label.className = 'missing'; $('groups').append(label); });\n  $('scope').textContent = groupName(GROUPS[0]) + '–' + groupNumbers[GROUPS.at(-1)] + ' · ' + rows.length + ' bord';\n}\nasync function refresh() {\n  if (!LIVE) { $('installation').showModal(); return; }\n  const requestedRound = round, request = ++requestNumber;\n  busy = true; render(); $('notice').className = ''; $('notice').textContent = 'Hämtar rond ' + requestedRound + ' från schack.se…';\n  const responses = await Promise.allSettled(GROUPS.map(group => fetchGroup(group, requestedRound)));\n  if (request !== requestNumber) return;\n  const failed = [];\n  responses.forEach((response, i) => {\n    const group = GROUPS[i];\n    if (response.status === 'fulfilled') games = games.filter(g => !(g.round === requestedRound && g.group === group)).concat(response.value);\n    else failed.push(group);\n  });\n  failures.set(requestedRound, failed); busy = false; render();\n  $('notice').className = failed.length ? 'warning' : '';\n  $('notice').textContent = failed.length ? `Kunde inte uppdatera grupp ${failed.join(', ')}. Eventuella tidigare listor för dessa grupper behålls. Klicka på Uppdatera för att försöka igen.` : 'Hämtad från schack.se · ' + new Date().toLocaleTimeString('sv-SE');\n}\nfunction selectRound(value) { round = value; render(); if (LIVE) void refresh(); }\nfor (let n = 1; n <= 5; n++) $('round').add(new Option('Rond ' + n, String(n)));\n$('round').onchange = () => selectRound(Number($('round').value));\n$('previous').onclick = () => { if (round > 1) selectRound(round - 1); };\n$('next').onclick = () => { if (round < 5) selectRound(round + 1); };\n$('refresh').onclick = refresh;\n$('displayMode').onclick = () => {\n  const enabled = document.body.classList.toggle('display-mode');\n  $('displayMode').setAttribute('aria-pressed', String(enabled));\n  $('displayMode').textContent = enabled ? 'Avsluta visningsläge' : 'Visningsläge';\n};\n$('print').onclick = () => {\n  const missing = GROUPS.filter(group => !currentGames().some(g => g.group === group));\n  if ((missing.length || failures.get(round)?.length) && !confirm('Bordslistan är ofullständig eller kunde inte uppdateras helt. Skriv ut ändå?')) return;\n  window.print();\n};\n$('installButton').onclick = () => $('installation').showModal();\nif (typeof BOOKMARKLET_URL !== 'undefined') {\n  for (const id of ['bookmarklet', 'dialogBookmarklet']) {\n    $(id).href = BOOKMARKLET_URL;\n    $(id).onclick = event => { event.preventDefault(); $('installation').showModal(); };\n  }\n  $('copyBookmarklet').onclick = async () => {\n    try { await navigator.clipboard.writeText(BOOKMARKLET_URL); $('installStatus').textContent = 'Kopierat. Skapa ett bokmärke och klistra in adressen i URL-fältet.'; }\n    catch { $('bookmarkCode').hidden = false; $('bookmarkCode').value = BOOKMARKLET_URL; $('bookmarkCode').focus(); $('bookmarkCode').select(); $('installStatus').textContent = 'Kopiera den markerade adressen och klistra in den i ett bokmärkes URL-fält.'; }\n  };\n}\nrender();\n$('prefixForm').onsubmit = async event => {\n  event.preventDefault();\n  if (!LIVE) { $('installation').showModal(); return; }\n  try { await detectGroups($('prefix').value); }\n  catch (error) { $('notice').className = 'warning'; $('notice').textContent = error.message; }\n};\nasync function initializeLive() {\n  document.body.classList.add('live-mode');\n  $('prefix').disabled = true;\n  $('notice').textContent = 'Läser turneringens grupper…';\n  try {\n    const sourceUrl = new URL(window.BERGER_SOURCE_URL || location.href);\n    if (sourceUrl.origin !== 'https://member.schack.se') throw Error('Öppna bokmärket på member.schack.se.');\n    const response = await fetch(sourceUrl.href, {cache:'no-store', signal:AbortSignal.timeout(20000)});\n    if (!response.ok) throw Error('Kunde inte läsa turneringens grupplänkar.');\n    const doc = new DOMParser().parseFromString(await response.text(), 'text/html');\n    const discovered = discoverGroups(doc);\n    if (!discovered.length) throw Error('Inga numrerade grupper hittades på källsidan.');\n    availableGroups = discovered;\n    const current = discovered.find(g => g.id === sourceUrl.searchParams.get('id'));\n    if (!current) throw Error('Gruppen i URL:en kunde inte identifieras. Öppna första gruppens sida.');\n    const startPrefix = current.prefix;\n    $('prefix').value = startPrefix;\n    const title = doc.title.split(' ' + current.prefix + '-' + current.number)[0];\n    $('tournamentTitle').textContent = title;\n    document.title = 'Bordslista · ' + title;\n    await detectGroups(startPrefix, doc, sourceUrl.searchParams.get('id'));\n  } catch (error) { $('notice').className = 'warning'; $('notice').textContent = error.message + ' Ange prefixet i textrutan, eller kör bokmärket igen från turneringens sida.'; }\n  finally { $('prefix').disabled = false; }\n}\nif (LIVE) { void initializeLive(); }\nelse {\n  $('refresh').textContent = 'Installera bokmärke';\n  fetch('initial.json').then(response => { if (!response.ok) throw Error(); return response.json(); }).then(data => {\n    games = validateGames(data.games); render();\n    $('notice').textContent = 'Förhandsvisning från ' + new Date(data.fetchedAt).toLocaleString('sv-SE') + '. Använd bokmärket på schack.se för aktuella bordslistor.';\n  }).catch(() => { $('notice').textContent = 'Installera bokmärket ovan och kör det på schack.se för att öppna bordslistan.'; });\n}\n</script></body></html>\n");
